INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4585220, 660293, 65234, '<td valign="top">Appropriately harsh lighting.</td>', 'Appropriately harsh lighting.', '2008-03-25 09:52:28.000000', NULL, 1),
(4585222, 661402, 65234, '<td valign="top">Interesting expression and composition.  Dunno'' about the vignette; seems too classy for a mug shot.</td>', 'Interesting expression and composition.  Dunno'' about the vignette; seems too classy for a mug shot.', '2008-03-25 09:53:20.000000', NULL, 1),
(4585227, 661527, 65234, '<td valign="top">Um, he sold them on the black market?  He looks entirely too cheery to be in police custody.  As an image, the haloes around his edges are a bit bothersome to me, and his eyes are too dark to have any life in them.</td>', 'Um, he sold them on the black market?  He looks entirely too cheery to be in police custody.  As an image, the haloes around his edges are a bit bothersome to me, and his eyes are too dark to have any life in them.', '2008-03-25 09:55:51.000000', NULL, 1),
(4585230, 660385, 65234, '<td valign="top">This must be Outdoor Booking.  Not sure why you didn''t crop tighter and avoid a lot of the blown sky and overexposed bits.</td>', 'This must be Outdoor Booking.  Not sure why you didn''t crop tighter and avoid a lot of the blown sky and overexposed bits.', '2008-03-25 09:57:08.000000', NULL, 1),
(4585233, 661523, 65234, '<td valign="top">He looks suitably despondent.</td>', 'He looks suitably despondent.', '2008-03-25 09:57:46.000000', NULL, 1),
(4585235, 661522, 65234, '<td valign="top">Well, now, that''s a bit disturbing.  Not showing remorse or dismay at all.</td>', 'Well, now, that''s a bit disturbing.  Not showing remorse or dismay at all.', '2008-03-25 09:58:26.000000', NULL, 1),
(4585240, 661401, 65234, '<td valign="top">Punny name.  Do they really put all that personal info on the card you have to hold?  Anyway ... certainly doesn''t look like there''s any regret here ;-)</td>', 'Punny name.  Do they really put all that personal info on the card you have to hold?  Anyway ... certainly doesn''t look like there''s any regret here ;-)', '2008-03-25 10:00:26.000000', NULL, 1),
(4585242, 660727, 65234, '<td valign="top">Next stop the emergency ward to have the bottle surgically removed.  No anesthesia required.</td>', 'Next stop the emergency ward to have the bottle surgically removed.  No anesthesia required.', '2008-03-25 10:01:15.000000', NULL, 1),
(4585246, 660756, 65234, '<td valign="top">My, what big eyes she has!  Light is a bit harsh which is OK for a mug shot, but I think you need to have the camera a little farther back from the subject.</td>', 'My, what big eyes she has!  Light is a bit harsh which is OK for a mug shot, but I think you need to have the camera a little farther back from the subject.', '2008-03-25 10:02:44.000000', NULL, 1),
(4585252, 660608, 65234, '<td valign="top">Another unrepentant prisoner.</td>', 'Another unrepentant prisoner.', '2008-03-25 10:03:46.000000', NULL, 1),
(4585254, 661316, 65234, '<td valign="top">Busted AND it looks like he lost the fight.  Not a great day for him.</td>', 'Busted AND it looks like he lost the fight.  Not a great day for him.', '2008-03-25 10:04:16.000000', NULL, 1),
(4585258, 660644, 65234, '<td valign="top">Not really finding this humorous despite the title; sorry.  It would certainly be a great shot for a hunger challenge, or poverty.</td>', 'Not really finding this humorous despite the title; sorry.  It would certainly be a great shot for a hunger challenge, or poverty.', '2008-03-25 10:05:46.000000', NULL, 1),
(4585264, 661016, 65234, '<td valign="top">Too cute!!  I know how hard it is to get a hamster in focus, never mind posed.  Great shot :-)</td>', 'Too cute!!  I know how hard it is to get a hamster in focus, never mind posed.  Great shot :-)', '2008-03-25 10:08:19.000000', NULL, 1),
(4585267, 661146, 65234, '<td valign="top">Spot-on stereotype ;-)  I do not think I would want to mess with this woman!</td>', 'Spot-on stereotype ;-)  I do not think I would want to mess with this woman!', '2008-03-25 10:10:12.000000', NULL, 1),
(4585275, 660037, 65234, '<td valign="top">I can imagine so many ways in which T.R. Tooth Fairy could have gotten himself in trouble ... but I''m trying to suppress those visions.  This COMPLETELY unflattering mug shot is bad enough!</td>', 'I can imagine so many ways in which T.R. Tooth Fairy could have gotten himself in trouble ... but I''m trying to suppress those visions.  This COMPLETELY unflattering mug shot is bad enough!', '2008-03-25 10:14:34.000000', NULL, 1),
